  "externalPlc.slmpDevices": "部件的 PLC 标签使用器件地址，例如 D100（数据寄存器）、M10（内部继电器）、X1A（输入）、Y0（输出）、B1A（链接继电器）、W10（链接寄存器）、TN5（定时器当前值）或 CN3（计数器当前值）。X、Y、B、W、SB、SW、DX、DY 使用十六进制，其余使用十进制。位器件使用 BOOL，寄存器使用 INT、DINT 或 REAL。对于带输入模块的 CPU，部件要写入的 X 地址应避开模块所占地址，否则 CPU 每次扫描都会覆盖该地址。",
