  "trainingLessons.monitoringBrief": "对比正常输送与模拟堵料，保存实训记录。",
  "trainingLessons.monitoringCheck": "JamAlarm 接通，BeltRun 断开。关闭 InjectJam 后，依次给 Reset 和 Start 发脉冲，再停止仿真并查看历史记录。",
  "trainingLessons.monitoringStep": "启动输送机。在「运行验证」添加 BeltRun 和 JamAlarm，为 JamAlarm 设置报警规则并开始记录。开启 InjectJam 后确认报警。",
  "trainingLessons.motor": "电机启停",
  "trainingLessons.motorBrief": "搭建带运行反馈的电机自保持逻辑，并排查故障。",
  "trainingLessons.motorCheck": "启动脉冲结束后 Run 保持。停止或故障时 Run 断开，故障清除后需复位。",
  "trainingLessons.motorStep": "在 PLC 中查看 Start、Stop、Run 和 Running，追踪运行反馈定时器，再执行电机故障用例。",
  "trainingLessons.pallet": "机器人码垛",
  "trainingLessons.palletBrief": "将箱体排成一层，再由机器人叠放到托盘上。",
  "trainingLessons.palletCheck": "运行项目测试，核对进料、成层、机器人码垛和托盘移库。",
  "trainingLessons.palletStep": "选中码垛机器人，查看取整层及各层放置作业如何切换。",
