  "tutorial.waiting": "教程保留在{project}项目中，可返回继续。",
  "tutorialSteps.appMenuBody": "左上角徽标下有文件、编辑、视图、仿真和帮助菜单。点击徽标或按 Alt 打开。",
  "tutorialSteps.appMenuTitle": "应用菜单",
  "tutorialSteps.boxBody": "打开「产品」标签，点击 Box（箱子），再点击输送机起点附近的标记。运行仿真时，箱子会沿输送机移动。",
  "tutorialSteps.boxHint": "在输送机上放置箱子",
  "tutorialSteps.boxTitle": "在输送机上放置箱子",
  "tutorialSteps.continue": "继续",
  "tutorialSteps.doneBody": "你已放置设备、添加传感器，使用 PLC 程序控制了产线，并在运行中修改了程序。这些操作同样适用于其他产线。\n\n产线和程序都保存在当前项目中。要恢复联锁，请将 TRUE 改回 FALSE 并重新加载。",
  "tutorialSteps.doneTitle": "已完成",
  "tutorialSteps.dropBody": "打开底部部件目录的「设备」，选择 Roller Conveyor（滚筒输送机），然后点击视口中标记附近的位置放置。",
  "tutorialSteps.dropHint": "在此处附近放置",
  "tutorialSteps.dropTitle": "放置输送机",
  "tutorialSteps.editBody": "你可以修改程序来改变输送机动作。在 PLC 标签页找到 IF {sensor} THEN 下面这一行。\n\n{line}\n\n将该行的 FALSE 改为 **TRUE**，然后点击「重新加载」。仿真运行期间，编辑在重新加载后生效，随后输送机启动，箱子将离开末端。\n\n错误会标红，并列在「问题」面板中。",
  "tutorialSteps.editTitle": "修改程序",
  "tutorialSteps.finish": "完成",
  "tutorialSteps.gotIt": "知道了",
  "tutorialSteps.interlockBody": "输送机把箱子送至出料端。箱子遮挡传感器光束后，程序停止输送机，箱子留在原处。\n\n在 PLC 标签页观察 **{sensor}** 变为 TRUE，**{conveyor}** 变为 FALSE。",
  "tutorialSteps.interlockTitle": "观察联锁",
  "tutorialSteps.lookBody": "移动相机观察场景。滚轮可缩放，按住{nav:orbit}可环绕，按住{nav:pan}可平移。按住鼠标右键并使用{key:fly.forward}{key:fly.left}{key:fly.back}{key:fly.right}飞行，按{key:fly.down}和{key:fly.up}下降和上升。移动相机继续。",
  "tutorialSteps.lookTitle": "观察场景",
  "tutorialSteps.playBody": "点击「运行」。物理仿真启动后，输送机会带动箱子沿产线移动。",
  "tutorialSteps.playTitle": "运行仿真",
  "tutorialSteps.plcBody": "这是部件旁边的 PLC 标签页。可在此读取和编辑程序，点击「运行」时将执行这里的程序。\n\n仿真运行时，各变量旁显示实时值。",
  "tutorialSteps.plcTitle": "查看程序",
  "tutorialSteps.runBody": "点击「运行」，让程序控制产线。",
  "tutorialSteps.runTitle": "再次运行",
  "tutorialSteps.sensorBody": "打开「器件」标签，点击 Photo Eye（光电传感器），再点击出料端的标记。传感器会吸附到侧栏并横向对准输送机，以检测箱子。",
  "tutorialSteps.sensorHint": "在出料端放置传感器",
  "tutorialSteps.sensorTitle": "添加出料传感器",
  "tutorialSteps.shortcutsBody": "工具、吸附和漫游模式都可以使用快捷键。按 **{key:ui.shortcuts}** 或打开工具栏的帮助菜单，可随时查看完整列表。",
  "tutorialSteps.shortcutsTitle": "键盘快捷键",
  "tutorialSteps.start": "开始",
  "tutorialSteps.stopBody": "点击「停止」。箱子会回到初始位置，可在添加控制程序后再次运行。",
  "tutorialSteps.stopTitle": "停止仿真并接线",
  "tutorialSteps.tagBody": "程序通过 PLC 标签控制部件。输送机已选中。在属性检查器高亮的 Run Tag 字段中输入 **{tag}**，再按 Enter。",
  "tutorialSteps.tagTitle": "给输送机设置标签",
  "tutorialSteps.watchBody": "还没有控制逻辑，箱子会直接从末端掉下。接下来用传感器和程序实现停止控制。",
  "tutorialSteps.watchTitle": "箱子离开输送机",
  "tutorialSteps.welcomeBody": "搭建一条可运行的输送线，并使用 PLC 逻辑控制它。整个教程只需几分钟。\n\n练习在独立项目中进行，搭建成果会保留下来。",
  "tutorialSteps.welcomeTitle": "搭建第一条产线",
  "tutorialSteps.writeBody": "PLC 程序循环读取输入并驱动输出。这个程序读取传感器，在箱子到达时停止输送机。\n\n{code}\n\n点击下方按钮，以同样的方式将传感器标记为 **{sensor}**，再把程序加载到 PLC 标签页。",
  "tutorialSteps.writeCta": "设置传感器和程序",
  "tutorialSteps.writeTitle": "编写程序",
